Snapshot* LangCtrl::activated_snapshot = nullptr;

namespace LangCtrl{
std::string_view embbedDataSnapshot(){
    // FIXME: this should be generated by download script
    return "";
}
}


void LangCtrl::InitEmbbedData(){
    std::string_view embbedDataSnapshot = LangCtrl::embbedDataSnapshot();
    GOOGLE_PROTOBUF_VERIFY_VERSION;

    static Snapshot snapshot;
    if(!snapshot.ParseFromString(embbedDataSnapshot)){
        PaperLogger.error("Invalid embbed data.");
        return;
    }

    activated_snapshot = &snapshot;

    if(snapshot.has_basegamecsvtranslation()){
        auto & base_translate = snapshot.basegamecsvtranslation();
        SSL10n::Database::PolyglotFormat::AddCSVContent(base_translate.data(), base_translate.size());
    }
    
    // TODO
    // auto siraRes = LangCtrl::siraLocalizerModResource();
    // SSL10n::Database::PolyglotFormat::AddCSVContent(siraRes.data(), siraRes.size());


    auto loaded_mods = modloader::get_loaded();
    auto metadata = snapshot.mods().find("ModMetadata");
    if(metadata != snapshot.mods().end()){
        if(metadata->second.datas_size()> 0){
            auto & data = metadata->second.datas(0);
            // TODO
            // loadedResourceMd5.insert(data);
            SSL10n::Database::PolyglotFormat::AddCSVContent(data.csv_content().data(), data.csv_content().size());
        }
    }

    for(auto & dat : snapshot.mods()){
        PaperLogger.info("Embbed translate for mod id {}", dat.first);
    }

    for(auto mod : loaded_mods){
        auto it = snapshot.mods().find(mod.info.id);
        if(it == snapshot.mods().end()){
            PaperLogger.info("Translate data for {} not found.", mod.info.id);
            continue;
        }
        PaperLogger.info("Load Embbed mod translate for {}", mod.info.id);

        auto & datas = it->second.datas();

        for(auto &versionData : datas){
            PaperLogger.info("Try loading version {}",versionData.version());
            std::string versionRange = versionData.version().data();

            if(versionRange.size() == 0
                || (versionRange[0] == '\0')
                || (versionRange[0] == '*' && versionRange[1] == '\0')
            ){
                // load the version
                PaperLogger.info("Translate will load.");
            }else{
                auto mod_version = semver::try_parse(mod.info.version);
                if(mod_version.has_value()){
                    semver::range_set rs;
                    if(semver::parse(versionRange, rs)){
                        if(!rs.contains(mod_version.value())){
                            PaperLogger.info("Mod version {} doesn't match embbed data version {}, skip this.", mod.info.version, versionRange);
                            continue;
                        }
                    }else{
                        PaperLogger.info("Version '{}' broken in embbed data. Anyway we will load the translate.", versionData.version());
                    }
                }else{
                    PaperLogger.info("Mod version parse failed. Anyway we will load the translate.");
                }
            }

            //loadedResourceMd5.insert(versionData.md5);
            SSL10n::Database::PolyglotFormat::AddCSVContent(versionData.csv_content().data(), versionData.csv_content().size());
            break;
        }
    }
}